    and ws.worker_id = #{workerId}
    and ws.community_id = #{communityId}
    and ws.work_status = #{workStatus}
    and u.nick_name like concat('%', #{workerName}, '%')

order by ws.skill_id

select ws.skill_id, ws.worker_id, ws.community_id, ws.skill_tags, ws.work_status, ws.current_load, ws.total_finished, ws.avg_response, ws.create_by, ws.create_time, ws.update_by, ws.update_time, u.nick_name as worker_name, u.phonenumber as worker_phone, c.community_name as community_name, (select count(1) from worker_skill ws2 where ws2.worker_id = ws.worker_id) as skill_id2 from worker_skill ws inner join sys_user u on ws.worker_id = u.user_id inner join sys_user_role ur on u.user_id = ur.user_id inner join sys_role r on ur.role_id = r.role_id left join community c on ws.community_id = c.community_id where u.status = '0' and u.del_flag = '0' and r.role_key = 'worker' and r.status = '0' and r.del_flag = '0' and ws.work_status = '0'
and ws.community_id = #{communityId}
group by ws.skill_id, ws.worker_id, ws.community_id, ws.skill_tags, ws.work_status, ws.current_load, ws.total_finished, ws.avg_response, ws.create_by, ws.create_time, ws.update_by, ws.update_time, u.nick_name, u.phonenumber, c.community_name order by ws.current_load asc, ws.avg_response asc

