update worker_skill
community_id = #{communityId}, skill_tags = #{skillTags}, work_status = #{workStatus}, update_by = #{updateBy}, update_time = sysdate()
where skill_id = #{skillId}

update worker_skill
set current_load = (
    select count(1) from repair_order o
    where o.del_flag = '0' and o.assignee_id = #{workerId}
      and o.order_status in ('assigned','accepted','arrived','repairing','repaired','appealed')
)
where worker_id = #{workerId}
